import { http } from './http.js'

export async function getConnections() {
    return http.get('/api/connections')
}

export async function addConnection(connection) {
    if(connection.type !== 'postgresql') {
        delete connection.schema
    }

    return http.post('/api/connection', connection)
}

export async function getConnection(connectionId, database, abortControllerSignal) {
    return http.get(`/api/connection/${connectionId}?database=${database}`, abortControllerSignal)
}

export async function getConnectionTable(connectionId, database, tableName) {
    return http.get(`/api/connection/${connectionId}/${tableName}?database=${database}`)
}

export async function runQuery(connectionId, database, query) {
    return http.post(`/api/connection/${connectionId}/query?database=${database}`, { query })
}

export async function getCount(connectionId, database, tableName, hasWhere, query) {
    return http.post(`/api/connection/${connectionId}/count?database=${database}`, { tableName, hasWhere, query })
}

export async function updateConnection(connection) {
    const connectionid = connection.id

    delete connection.id
    delete connection.created_at

    if(connection.type !== 'postgresql') {
        delete connection.schema
    }

    return http.put(`/api/connection/${connectionid}`, connection)
}

export async function deleteConnection(connectionId) {
    return http.delete(`/api/connection/${connectionId}`)
}

export async function getSavedQueries(connectionId) {
    return http.post(`/api/connection/${connectionId}/saved_queries`)
}

export async function addSavedQuery(connectionId, name, query) {
    return http.post(`/api/connection/${connectionId}/saved_query`, {
        name,
        query,
    })
}

export async function deleteSavedQuery(savedQueryId) {
    return http.delete(`/api/saved_query/${savedQueryId}`)
}

export async function importFile(connectionId, database, file) {
    const formData = new FormData()
    formData.append('database', database)
    formData.append('file', file)

    return http.postMultipart(`/api/connection/${connectionId}/import`, formData)
}

import fs from 'fs'
import { execSync } from 'child_process'

const incrementType = process.argv.slice(2)

if (incrementType.length === 0) {
    console.log('Please specify one of these: --major | --minor | --patch | --undo')
    process.exit(1)
}

const installFile = 'install.sh'

const incrementVersion = (version, type) => {
    const versionParts = version.split('.').map(Number)

    switch (type) {
        case '--major':
            versionParts[0] += 1
            versionParts[1] = 0
            versionParts[2] = 0
            break
        case '--minor':
            versionParts[1] += 1
            versionParts[2] = 0
            break
        case '--patch':
            versionParts[2] += 1
            break
    }

    return versionParts.join('.')
}

try {
    const lastTag = execSync('git describe --tags --abbrev=0').toString().trim()
    if (!lastTag) {
        throw new Error('No git tags found')
    }

    if (incrementType.includes('--undo')) {
        // check if last commit is "chore: bump version"
        const lastCommit = execSync('git log -1 --pretty=%B').toString().trim()
        if (lastCommit !== 'chore: bump version') {
            console.log('Last commit is not "chore: bump version" so nothing to undo')
            process.exit(1)
        }
        execSync(`git tag -d ${lastTag}`)
        execSync(`git stash`)
        execSync(`git reset --hard HEAD~1`)
        execSync(`git stash pop`)
        process.exit(0)
    }

    const lastVersion = lastTag.startsWith('v') ? lastTag.slice(1) : lastTag
    const newVersion = incrementVersion(lastVersion, incrementType[0])
    const data = fs.readFileSync(installFile, 'utf8')
    const regex = /(wget https:\/\/github\.com\/flawiddsouza\/jellyadmin\/releases\/download\/)v[0-9]+(\.[0-9]+)*\/(jellyadmin-linux\.gz)/
    const replacement = `$1v${newVersion}/$3`
    const updatedData = data.replace(regex, replacement)

    fs.writeFileSync(installFile, updatedData, 'utf8')

    execSync(`git add ${installFile}`)
    execSync(`git commit -m "chore: bump version"`)
    execSync(`git tag v${newVersion}`)

    console.log(`Version number updated to v${newVersion}`)
} catch (err) {
    console.error(err)
    process.exit(1)
}

import SQLite3 from 'better-sqlite3'
import path from 'path'

const db = new SQLite3(path.resolve('store.db'))

db.pragma('journal_mode = WAL')

export function migrate() {
    const userVersion = db.prepare('PRAGMA user_version').pluck().get()

    let migrationMessage = null

    if(userVersion === 0) {
        db.prepare(`
            CREATE TABLE IF NOT EXISTS "connections" (
                id INTEGER,
                name TEXT,
                type TEXT,
                host TEXT,
                port INTEGER,
                username TEXT,
                password TEXT,
                database TEXT,
                schema TEXT,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                PRIMARY KEY(id)
            )
        `).run()

        db.prepare(`PRAGMA user_version = 1`).run()

        migrationMessage = 'Databased initialized'
    }

    if(userVersion === 1) {
        db.prepare(`
            CREATE TABLE IF NOT EXISTS "saved_queries" (
                id INTEGER,
                connection_id INTEGER,
                name TEXT,
                query TEXT,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                PRIMARY KEY(id),
                FOREIGN KEY(connection_id) REFERENCES connections(id)
            )
        `).run()

        db.prepare(`PRAGMA user_version = 2`).run()

        migrationMessage = 'saved_queries table created'
    }

    if(migrationMessage !== null) {
        return migrationMessage
    }

    return 'Nothing to migrate'
}

export function getConnections() {
    return db.prepare('SELECT * FROM connections ORDER BY name, database').all()
}

export function addConnection(name, type, host, port, username, password, database, schema) {
    const result = db.prepare('INSERT INTO connections(name, type, host, port, username, password, database, schema) VALUES(?, ?, ?, ?, ?, ?, ?, ?)').run(name, type, host, port, username, password, database, schema)
    return getConnection(result.lastInsertRowid)
}

export function getConnection(connectionId, database) {
    const connection = db.prepare('SELECT * FROM connections WHERE id = ?').get(connectionId)
    if(!connection) {
        throw new Error('Given connection id does not exist')
    }
    connection.connection_url = `${connection.type}://${connection.username}:${connection.password}@${connection.host}:${connection.port}/${database !== 'undefined' ? database : connection.database}`
    return connection
}

export function updateConnection(connectionId, name, type, host, port, username, password, database, schema) {
    db.prepare('UPDATE connections SET name=?, type=?, host=?, port=?, username=?, password=?, database=?, schema=?, updated_at=CURRENT_TIMESTAMP WHERE id = ?').run(name, type, host, port, username, password, database, schema, connectionId)
    return getConnection(connectionId)
}

export function deleteConnection(connectionId) {
    const connection = db.prepare('SELECT * FROM connections WHERE id = ?').get(connectionId)
    if(!connection) {
        throw new Error('Given connection id does not exist')
    }
    return db.prepare('DELETE FROM connections WHERE id = ?').run(connectionId)
}

export function getSavedQueries(connectionId) {
    return db.prepare('SELECT * FROM saved_queries WHERE connection_id = ? ORDER BY created_at DESC').all(connectionId)
}

export function addSavedQuery(name, query, connectionId) {
    const result = db.prepare('INSERT INTO saved_queries(name, query, connection_id) VALUES(?, ?, ?)').run(name, query, connectionId)
    return getSavedQuery(result.lastInsertRowid)
}

export function getSavedQuery(savedQueryId) {
    return db.prepare('SELECT * FROM saved_queries WHERE id = ?').get(savedQueryId)
}

export function deleteSavedQuery(savedQueryId) {
    return db.prepare('DELETE FROM saved_queries WHERE id = ?').run(savedQueryId)
}

import * as db from './db.js'
import postgres from 'postgres'
import mysql from 'mysql2/promise'
import { CONNECTION_TYPES } from './constants.js'

let connectionCache = {}

async function getConnection(connectionId, database) {
    if(database === undefined) {
        throw new Error('database is a mandatory parameter for getConnection')
    }

    const key = `${connectionId}-${database}`

    if(key in connectionCache === false || (key in connectionCache && connectionCache[key].connection.type === 'mysql' && connectionCache[key].sql.connection._closing)) {
        const connection = db.getConnection(connectionId, database)
        let sql = null

        if(connection.type === CONNECTION_TYPES.POSTGRESQL) {
            sql = postgres(connection.connection_url, {
                connect_timeout: 5,
                types: {
                    date: {
                        to: 1184,
                        from: [1082, 1083, 1114, 1184],
                        serialize: (date) => date,
                        parse: (date) => date
                    }
                }
            })
        }

        if(connection.type === CONNECTION_TYPES.MYSQL) {
            sql = await mysql.createConnection({
                host: connection.host,
                port: connection.port,
                user: connection.username,
                password: [REDACTED],
                database: database !== 'undefined' ? database : connection.database,
                dateStrings: true
            })
        }

        connectionCache[key] = {
            connection,
            sql
        }
    }

    return connectionCache[key]
}

export async function getDatabases(connectionId, database) {
    try {
        const { connection, sql } = await getConnection(connectionId, database)

        let rows = []

        if(connection.type === CONNECTION_TYPES.POSTGRESQL) {
            rows = await sql`
                SELECT datname as database FROM pg_database
                WHERE datistemplate = false
            `
        }

        if(connection.type === CONNECTION_TYPES.MYSQL) {
            [ rows ] = await sql.execute(`
                SHOW DATABASES
            `)

            rows = rows.map(row => ({
                database: row.Database
            }))
        }

        return rows
    } catch(e) {
        console.error(e)
        throw new Error(e.message)
    }
}

export async function getTables(connectionId, database) {
    try {
        const { connection, sql } = await getConnection(connectionId, database)

        let rows = []
        let tableColumns = []

        if(connection.type === CONNECTION_TYPES.POSTGRESQL) {
            rows = await sql`
                SELECT
                    table_name
                FROM
                    information_schema.tables
                WHERE
                    table_schema = ${connection.schema}
                ORDER BY table_name
            `

            tableColumns = await sql`
                SELECT table_name, column_name
                FROM information_schema.columns
                WHERE table_schema = ${connection.schema}
                ORDER BY table_name, ordinal_position
            `
        }

        if(connection.type === CONNECTION_TYPES.MYSQL) {
            [ rows ] = await sql.execute(`
                SELECT
                    TABLE_NAME as table_name
                FROM
                    information_schema.tables
                WHERE
                    table_schema = '${database}'
                ORDER BY table_name
            `);

            [ tableColumns ] = await sql.execute(`
                SELECT TABLE_NAME as table_name, COLUMN_NAME as column_name
                FROM information_schema.columns
                WHERE table_schema = '${database}'
                ORDER BY TABLE_NAME, ORDINAL_POSITION
            `)
        }

        rows.forEach(row => {
            row.columns = tableColumns.filter(item => item.table_name === row.table_name).map(item => item.column_name)
        })

        return rows
    } catch(e) {
        console.error(e)
        throw new Error(e.message)
    }
}

export async function getTableDetails(connectionId, database, tableName) {
    try {
        const { connection, sql } = await getConnection(connectionId, database)

        let columns = []
        let indexes = []
        let foreignKeys = []

        if(connection.type === CONNECTION_TYPES.POSTGRESQL) {
            columns = await sql`
                SELECT
                    column_name as name,
                    data_type as type,
                    CASE WHEN is_nullable = 'YES' THEN true ELSE false END as nullable,
                    column_default as default_value,
                    false as primary_column,
                    false as auto_increment,
                    pg_catalog.col_description(format('"%s"."%s"', table_schema, table_name)::regclass::oid, ordinal_position) as comment
                FROM
                    information_schema.columns
                WHERE
                    table_schema = ${connection.schema} AND table_name = ${tableName}
                ORDER BY ordinal_position
            `

            indexes = await sql`
                SELECT
                    CASE WHEN starts_with(indexname, 'PK') THEN 'PRIMARY' WHEN starts_with(indexdef, 'CREATE UNIQUE') THEN 'UNIQUE' ELSE 'INDEX' END as type,
                    indexdef as column,
                    indexname as name
                FROM pg_indexes
                WHERE schemaname = ${connection.schema} AND tablename = ${tableName};
            `

            foreignKeys = await sql`
                SELECT
                    tc.constraint_name as name,
                    kcu.column_name as column,
                    ccu.table_name AS foreign_table,
                    ccu.column_name AS foreign_column
                FROM
                    information_schema.table_constraints AS tc
                JOIN information_schema.key_column_usage AS kcu ON tc.constraint_name = kcu.constraint_name AND tc.table_schema = kcu.table_schema
                JOIN information_schema.constraint_column_usage AS ccu ON ccu.constraint_name = tc.constraint_name AND ccu.table_schema = tc.table_schema
                WHERE tc.constraint_type = 'FOREIGN KEY' AND tc.table_schema = ${connection.schema} AND tc.table_name = ${tableName};
            `
        }

        if(connection.type === CONNECTION_TYPES.MYSQL) {
            let result1 = await sql.execute(`
                SELECT
                    COLUMN_NAME as name,
                    COLUMN_TYPE as type,
                    CASE WHEN IS_NULLABLE = 'YES' THEN true ELSE false END as nullable,
                    COLUMN_DEFAULT as default_value,
                    CASE WHEN COLUMN_KEY = 'PRI' THEN true ELSE false END as primary_column,
                    CASE WHEN EXTRA = 'auto_increment' THEN true ELSE false END as auto_increment,
                    COLUMN_COMMENT as comment
                FROM
                    information_schema.columns
                WHERE
                    table_schema = '${database}' AND table_name = '${tableName}'
                ORDER BY ordinal_position
            `)

            columns = result1[0]

            let result2 = await sql.execute(`
                SHOW INDEX FROM \`${tableName}\`;
            `)

            indexes = result2[0].map(row => {
                let type = ''

                if(row.Key_name === 'PRIMARY') {
                    type = 'PRIMARY'
                } else {
                    if(row.Non_unique) {
                        type = 'INDEX'
                    } else {
                        type = 'UNIQUE'
                    }
                }

                return {
                    type,
                    column: row.Column_name,
                    name: row.Key_name
                }
            })

            let result3 = await sql.execute(`
                SELECT
                    CONSTRAINT_NAME as name,
                    COLUMN_NAME as 'column',
                    REFERENCED_TABLE_NAME as foreign_table,
                    REFERENCED_COLUMN_NAME as foreign_column
                FROM information_schema.KEY_COLUMN_USAGE
                WHERE
                    TABLE_SCHEMA = "${database}" AND TABLE_NAME = "${tableName}" AND REFERENCED_COLUMN_NAME IS NOT NULL
            `)

            foreignKeys = result3[0]
        }

        return {
            columns,
            indexes,
            foreignKeys
        }
    } catch(e) {
        console.error(e)
        throw new Error(e.message)
    }
}

export async function runQuery(connectionId, database, query) {
    try {
        const { connection, sql } = await getConnection(connectionId, database)

        let rows = []

        if(connection.type === CONNECTION_TYPES.POSTGRESQL) {
            rows = await sql.unsafe(query)
        }

        if(connection.type === CONNECTION_TYPES.MYSQL) {
            [ rows ] = await sql.query(query)
        }

        return rows
    } catch(e) {
        console.error(e)
        throw new Error(e.message)
    }
}

import express from 'express'
import * as db from './db.js'
import * as connection from './connection.js'
import { assert, object, number, string, type, enums, optional, nullable } from 'superstruct'
import path from 'path'
import { CONNECTION_TYPES } from './constants.js'
import { exec } from 'child_process'
import multer from 'multer'
import fs from 'fs'

const app = express()
const port = process.env.PORT ?? 5040

app.use(express.json({
    limit: '10mb'
}))
app.use(express.static(path.join(path.dirname(process.argv[1]), 'public')))

// URL rewriting for vue router web history mode
app.use((req, res, next) => {
    if(req.method === 'GET' && req.url.startsWith('/api') === false) {
        res.sendFile(path.join(path.dirname(process.argv[1]), 'public', 'index.html'))
        return
    }
    next()
})

const apiRouter = express.Router()

console.log(db.migrate())

apiRouter.get('/connections', (_req, res) => {
    try {
        const connections = db.getConnections()
        res.send(connections)
    } catch(e) {
        console.error(e)
        res.send(e.message)
    }
})

const connectionStruct = {
    name: string(),
    type: enums([CONNECTION_TYPES.POSTGRESQL, CONNECTION_TYPES.MYSQL]),
    host: string(),
    port: number(),
    username: string(),
    password: string(),
    database: nullable(string()),
    schema: optional(string())
}

apiRouter.post('/connection', (req, res) => {
    try {
        const newConnectionStruct = object(connectionStruct)

        assert(req.body, newConnectionStruct)

        if(req.body.type === CONNECTION_TYPES.MYSQL) {
            assert(req.body, type({
                schema: enums([null, undefined])
            }))
        }

        if(req.body.type === CONNECTION_TYPES.POSTGRESQL) {
            assert(req.body, type({
                schema: string()
            }))
        }

        const createdConnection = db.addConnection(
            req.body.name,
            req.body.type,
            req.body.host,
            req.body.port,
            req.body.username,
            req.body.password,
            req.body.database,
            req.body.schema
        )

        res.status(201).send(createdConnection)
    } catch(e) {
        console.error(e)
        res.send(e.message)
    }
})

apiRouter.get('/connection/:connection_id', async(req, res) => {
    let details = null

    try {
        details = db.getConnection(req.params.connection_id, req.query.database)
    } catch(e) {
        res.status(400).send(e.message)
        return
    }

    let databases = {}

    try {
        databases.data = await connection.getDatabases(req.params.connection_id, req.query.database)
        databases.success = true
    } catch(e) {
        databases.data = e.message
        databases.success = false
    }

    try {
        const tables = await connection.getTables(req.params.connection_id, req.query.database)

        res.send({
            details,
            databases,
            tables: {
                success: true,
                data: tables
            }
        })
    } catch(e) {
        res.send({
            details,
            databases,
            tables: {
                success: false,
                data: e.message === 'write CONNECT_TIMEOUT undefined:undefined' ? 'Unable to establish connection with database' : e.message
            }
        })
    }
})

apiRouter.put('/connection/:connection_id', async(req, res) => {
    try {
        const newConnectionStruct = object({
            ...connectionStruct,
            updated_at: string()
        })

        assert(req.body, newConnectionStruct)

        if(req.body.type === CONNECTION_TYPES.MYSQL) {
            assert(req.body, type({
                schema: enums([null, undefined])
            }))
        }

        if(req.body.type === CONNECTION_TYPES.POSTGRESQL) {
            assert(req.body, type({
                schema: string()
            }))
        }

        const updatedConnection = db.updateConnection(
            req.params.connection_id,
            req.body.name,
            req.body.type,
            req.body.host,
            req.body.port,
            req.body.username,
            req.body.password,
            req.body.database,
            req.body.schema
        )

        res.status(200).send(updatedConnection)
    } catch(e) {
        console.error(e)
        res.send(e.message)
    }
})

apiRouter.delete('/connection/:connection_id', async(req, res) => {
    try {
        db.deleteConnection(req.params.connection_id)
        res.send({
            data: 'Connection deleted'
        })
    } catch(e) {
        console.error(e)
        res.send(e.message)
    }
})

apiRouter.get('/connection/:connection_id/:table_name', async(req, res) => {
    try {
        const tableDetails = await connection.getTableDetails(req.params.connection_id, req.query.database, req.params.table_name)
        res.send(tableDetails)
    } catch(e) {
        res.status(400).send(e.message)
    }
})

apiRouter.post('/connection/:connection_id/query', async(req, res) => {
    try {
        const result = await connection.runQuery(req.params.connection_id, req.query.database, req.body.query)
        res.send(result)
    } catch(e) {
        res.status(400).send(e.message)
    }
})

apiRouter.post('/connection/:connection_id/count', async(req, res) => {
    try {
        const activeConnection = db.getConnection(req.params.connection_id)

        let count = null

        // if mysql & no where condition, we use approx count for table with rows > 2,00,000
        if(activeConnection.type === 'mysql' && req.body.hasWhere === false) {
            const result = await connection.runQuery(
                req.params.connection_id,
                req.query.database,
                `SHOW TABLE STATUS LIKE '${req.body.tableName}'`
            )

            if(result[0].Rows > 200000) {
                count = result[0].Rows
            }
        }

        // if postgresql & no where condition, we use approx count for table with rows > 2,00,000
        if(activeConnection.type === 'postgresql' && req.body.hasWhere === false){
            const result = await connection.runQuery(
                req.params.connection_id,
                req.query.database,
                `
                    SELECT reltuples::bigint AS rows
                    FROM pg_class
                    WHERE oid = '${activeConnection.schema}.${req.body.tableName}'::regclass
                `
            )

            if(result[0].rows > 200000) {
                count = result[0].rows
            }
        }

        if(count === null) {
            const result = await connection.runQuery(req.params.connection_id, req.query.database, req.body.query)
            count = result[0].count
        }

        res.send({
            count
        })
    } catch(e) {
        res.status(400).send(e.message)
    }
})

apiRouter.post('/connection/:connection_id/saved_queries', async(req, res) => {
    try {
        const queries = db.getSavedQueries(req.params.connection_id)
        res.send(queries)
    } catch(e) {
        res.status(400).send(e.message)
    }
})

apiRouter.post('/connection/:connection_id/saved_query', async(req, res) => {
    try {
        const newQuery = db.addSavedQuery(req.body.name, req.body.query, req.params.connection_id)
        res.status(201).send(newQuery)
    } catch(e) {
        res.status(400).send(e.message)
    }
})

apiRouter.delete('/saved_query/:saved_query_id', async(req, res) => {
    try {
        db.deleteSavedQuery(req.params.saved_query_id)
        res.send({
            data: 'Saved Query deleted'
        })
    } catch(e) {
        res.status(400).send(e.message)
    }
})

const upload = multer({ dest: 'uploads/' })

apiRouter.post('/connection/:connection_id/import', upload.single('file'), async (req, res) => {
    try {
        const { connection_id } = req.params
        const { database } = req.body
        const filePath = req.file.path

        const connection = db.getConnection(connection_id, database)

        const command = `mysql --protocol=TCP -h ${connection.host} -P ${connection.port} -u ${connection.username} -p${connection.password} "${database}" < ${filePath}`

        console.log('import', { command })

        exec(command, (error, stdout, stderr) => {
            fs.unlinkSync(filePath)

            if (error) {
                res.status(500).send({ success: false, message: stderr })
                return
            }

            res.send({ success: true, message: 'Import completed successfully' })
        })
    } catch (e) {
        console.error(e)
        res.status(400).send(e.message)
    }
})

